"""Keep policy image inputs stable across Pillow security updates."""

import hashlib
from io import BytesIO

import numpy as np
from PIL import Image
import pytest


def patterned_image():
    y, x = np.indices((237, 319))
    pixels = np.stack(
        [(x * 17 + y * 7) % 256, (x * x + y * 11) % 256, (x * 3 + y * y) % 256],
        axis=-1,
    ).astype("uint8")
    return Image.fromarray(pixels)


# Captured with the qualified Pillow 12.2 runtime, not generated by the candidate.
@pytest.mark.parametrize(
    "method,size,expected",
    [
        ("BILINEAR", 224, "9949b8146124b2dcc3b11ac0b4e3ff098131250e4c4b9f86c4a12beb6de01585"),
        ("BILINEAR", 384, "7a4a835ca923759f6eb7b6eb3dafd92bb78c0b9abac20622c714e80b9ebb9924"),
        ("BICUBIC", 224, "fd0d176408db91026f4df73a81cac3f74cacad577af20a57ee1aae93954f8793"),
        ("BICUBIC", 384, "1b13f4af69ba4f5b2f22bde00408de39e188b0814b3a0f54373ce0134a9ac900"),
        ("LANCZOS", 224, "1c49cbd636b402fb88550e098ba3f0d2022e61ba04869d1a3bad3387d2ec616f"),
        ("LANCZOS", 384, "db27dd0057da449fff2b9ceca2dac0dced8a67353f5e9edfceccbd0efd399bfd"),
    ],
)
def test_policy_image_resize_preserves_pixels(method, size, expected):
    resized = patterned_image().resize((size, size), getattr(Image.Resampling, method))
    assert hashlib.sha256(resized.tobytes()).hexdigest() == expected


def test_png_and_grayscale_preserve_pixels():
    image = patterned_image()
    buffer = BytesIO()
    image.save(buffer, format="PNG")
    buffer.seek(0)
    with Image.open(buffer) as decoded:
        assert decoded.convert("RGB").tobytes() == image.tobytes()
    gray = Image.fromarray(np.asarray(image)[:, :, 0], mode="L").convert("RGB")
    assert hashlib.sha256(gray.tobytes()).hexdigest() == (
        "8f8d4079ef340d9ef366a8ad9f0177ea7d1d897cd9c8495e6b55520797cd75a1"
    )
